def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None


print(safe_divide(5, 2), safe_divide(1, 0))

class AgeError(Exception):
    pass


def validate_age(age):
    if age < 0 or age > 150:
        raise AgeError('Invalid age')
    return age


try:
    validate_age(-1)
except AgeError:
    print('AgeError raised')
